const icon=(n,s=18)=>`<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||ICONS.target}</svg>`;
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>`${Date.now().toString(36)}${Math.random().toString(36).slice(2,8)}`;
const pad=n=>String(n).padStart(2,'0');
const today=()=>dateISO(new Date());
function dateISO(d){return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;}
function dateObj(s){const [y,m,d]=String(s).split('-').map(Number);return new Date(y,m-1,d);}
function shiftDate(s,n){const d=dateObj(s);d.setDate(d.getDate()+n);return dateISO(d);}
function longDate(s){return dateObj(s).toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});}
function shortDate(s){return dateObj(s).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'});}
function nfmt(n,dec=0){return Number(n||0).toLocaleString('pt-BR',{maximumFractionDigits:dec,minimumFractionDigits:dec});}
function numberVal(v){const n=Number(String(v??'').replace(',','.'));return Number.isFinite(n)?n:0;}
function clone(o){return JSON.parse(JSON.stringify(o));}
function makeProfile(name){return {
 name:String(name||'Atleta').slice(0,70),theme:localStorage.getItem(GUEST_THEME_KEY)==='light'?'light':'dark',
 routines:{
  A:{name:'Peito e tríceps',exerciseIds:['supino','voador','triceps_polia']},
  B:{name:'Costas e bíceps',exerciseIds:['puxada','remada_baixa','rosca_scott']},
  C:{name:'Pernas e glúteos',exerciseIds:['legpress','extensora','flexora','abdutora']}
 },
 exercises:[],exercisePhotos:{},days:{},weights:[],supplements:[]
};}
function loadDB(){return {version:2,profiles:{}};} // Nada fica exposto antes da autenticação.
let db=loadDB();
let current=null; // UUID do usuário autenticado, nunca um PIN/perfil pré-criado.
const state={page:'dashboard',routine:'A',selectedDate:today(),calendarMonth:today().slice(0,7),modal:null,dayDraft:null,filter:'Todos',search:'',pickerFilter:'Todos',pickerSearch:'',pickerMode:'add',pickerIndex:-1,pickerRoutine:'A',progressExercise:'supino',progressMetric:'weight',fab:false,editSupplement:null,weightEdit:null};
function profile(){return db.profiles[current];}
function themeForUser(){return current&&db.profiles[current]?.theme==='light'?'light':!current&&localStorage.getItem(GUEST_THEME_KEY)==='light'?'light':'dark';}
function applyTheme(){const t=themeForUser();document.documentElement.dataset.theme=t;document.documentElement.style.colorScheme=t;const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=t==='light'?'#f4f8f5':'#0d1114';}
function themeToggle(compact=false){const light=themeForUser()==='light';return `<button type="button" class="theme-toggle ${compact?'theme-toggle-compact':''}" data-action="theme-toggle" aria-label="Ativar modo ${light?'escuro':'claro'}" title="Alternar para modo ${light?'escuro':'claro'}" aria-pressed="${light}">${icon(light?'moon':'sun',18)}<span>${light?'Modo escuro':'Modo claro'}</span></button>`;}
function setTheme(){if(current&&db.profiles[current]){db.profiles[current].theme=themeForUser()==='light'?'dark':'light';saveDB();}else{localStorage.setItem(GUEST_THEME_KEY,themeForUser()==='light'?'dark':'light');}render();toast('Tema '+(themeForUser()==='light'?'claro gelo':'escuro neon')+' ativado.');}
function saveDB(){if(!current||!db.profiles[current])return false;if(typeof window.formaPersist!=='function')return false;return window.formaPersist();}
function allExercises(){const photos=profile().exercisePhotos||{};return [...EXERCISES,...profile().exercises].map(e=>photos[e.id]?{...e,photo:photos[e.id]}:e);}
function exById(id){return allExercises().find(e=>e.id===id)||{id,name:'Exercício removido',group:'Outros',equipment:'',kind:'chest'};}
function day(s){return profile().days[s]||{activity:null,supplemented:false,taken:[],session:[],notes:'',minutes:''};}
function hasSupp(d){return !!(d.supplemented||(d.taken||[]).length);}
function isWorkout(t){return ['A','B','C'].includes(t);}
// Qualquer dia com musculação, cardio ou abdominal conta uma vez na streak.
// Suplementação e descanso (inclusive automático) nunca contam.
function isTrainingActivity(t){return ['A','B','C','cardio','abs'].includes(t);}
function streakStats(reference=today()){
 const dates=Object.keys(profile().days||{}).filter(d=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&d<=reference&&isTrainingActivity(profile().days[d]?.activity)).sort();
 let best=0,run=0;
 for(let i=0;i<dates.length;i++){
  run=i>0&&dates[i-1]===shiftDate(dates[i],-1)?run+1:1;
  best=Math.max(best,run);
 }
 const last=dates.at(-1)||null;
 const active=last===reference||last===shiftDate(reference,-1);
 return {current:active?run:0,best,doneToday:last===reference,lastDate:last,total:dates.length};
}
function streakPanel(compact=false){
 const st=streakStats();
 if(compact)return `<div class="streak-mini" aria-label="Sequência atual de ${st.current} dias e recorde de ${st.best} dias"><span class="streak-fire">${icon('flame',21)}</span><div><strong>${st.current} ${st.current===1?'dia':'dias'}</strong><small>Streak atual</small></div><span class="streak-record">Recorde <b>${st.best}</b></span></div>`;
 return `<div class="streak-panel" aria-label="Sequência atual de ${st.current} dias e recorde de ${st.best} dias"><div class="streak-panel-label">${icon('flame',17)} SEQUÊNCIA DE TREINOS</div><div class="streak-count">${st.current} <span>${st.current===1?'dia':'dias'}</span></div><div class="streak-panel-footer"><span>🏆 Recorde: <b>${st.best} ${st.best===1?'dia':'dias'}</b></span><span>${st.doneToday?'✓ Hoje está pago':st.current?'Treine hoje para continuar':'Registre seu primeiro treino'}</span></div></div>`;
}
// Uma celebração visual não cria sessões extras nem altera uma data salva.
function confettiCelebration(origin){
 document.querySelector('.confetti-layer')?.remove();
 const st=streakStats();
 const layer=document.createElement('div');layer.className='confetti-layer';layer.setAttribute('aria-hidden','true');
 const label=document.createElement('div');label.className='celebration-label';
 label.innerHTML=`<span class="celebration-emoji">🎉</span><strong>TREINO TÁ PAGO!</strong><small>${st.current} ${st.current===1?'dia':'dias'} de sequência 🔥</small>`;
 layer.appendChild(label);
 const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(!reduced){
  const colors=['#b9f770','#236a48','#e9c874','#a88cf0','#78cadd','#ffffff','#f39e78'];
  const rect=origin;
  const cx=rect?rect.left+rect.width/2:window.innerWidth/2;
  const cy=rect?rect.top+rect.height/2:window.innerHeight*.55;
  const count=window.innerWidth<600?65:105;
  for(let i=0;i<count;i++){
   const bit=document.createElement('i');bit.className='confetti-piece';
   const angle=Math.random()*Math.PI*2,range=140+Math.random()*Math.min(window.innerWidth*.45,410);
   bit.style.setProperty('--x',cx+'px');bit.style.setProperty('--y',cy+'px');
   bit.style.setProperty('--dx',Math.cos(angle)*range+'px');bit.style.setProperty('--dy',Math.sin(angle)*range+110+'px');
   bit.style.setProperty('--spin',(480+Math.random()*1200)*(Math.random()<.5?-1:1)+'deg');
   bit.style.setProperty('--delay',(Math.random()*130)+'ms');
   bit.style.setProperty('--duration',(1050+Math.random()*750)+'ms');
   bit.style.background=colors[i%colors.length];
   if(i%3===0)bit.style.borderRadius='50%';
   layer.appendChild(bit);
  }
 }
 document.body.appendChild(layer);
 window.setTimeout(()=>{if(layer.isConnected)layer.remove();},reduced?1650:2350);
}

function activity(d,s){return d.activity || (s<=today()?'rest':null);}
function actLabel(a){return {A:'Treino A',B:'Treino B',C:'Treino C',cardio:'Só cardio',abs:'Só abdominal',rest:'Descanso'}[a]||'Sem registro';}
function actColor(a){return {A:'green',B:'purple',C:'amber',cardio:'blue',abs:'blue',rest:'muted-tag'}[a]||'muted-tag';}
function workoutDates(){return Object.keys(profile().days).filter(d=>isWorkout(profile().days[d].activity)).sort();}
function workoutsInMonth(m){return workoutDates().filter(d=>d.startsWith(m)).length;}
function suppInMonth(m){return Object.entries(profile().days).filter(([d,r])=>d.startsWith(m)&&hasSupp(r)).length;}
function lastWeight(){return [...profile().weights].sort((a,b)=>a.date.localeCompare(b.date)).at(-1);}
function getEntries(exId){return Object.entries(profile().days).flatMap(([date,d])=>((d.session||[]).filter(x=>x.id===exId && (numberVal(x.weight)>0||numberVal(x.reps)>0)).map(x=>({...x,date})))).sort((a,b)=>a.date.localeCompare(b.date));}
