function pageHeading(kicker,title,subtitle,action=''){return `<div class="page-intro"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function empty(iconName,heading,sub,action=''){return `<div class="empty"><div class="empty-icon">${icon(iconName)}</div><strong>${heading}</strong><div class="small">${sub}</div>${action?`<div class="mt16">${action}</div>`:''}</div>`;}
function navItem(label,page,ic){return `<button class="nav-btn ${state.page===page?'active':''}" data-action="page" data-page="${page}">${icon(ic)} <span>${label}</span></button>`;}
function mobileItem(label,page,ic){return `<button class="${state.page===page?'active':''}" data-action="page" data-page="${page}">${icon(ic)}<span>${label}</span></button>`;}
function renderLogin(){
 const a=window.formaAuthState||{mode:'login'},mode=a.mode||'login',loading=!!a.pending;
 const labels={login:['ENTRAR NA SUA CONTA','Acesse seu espaço.','Entrar'],signup:['CRIAR CONTA','Comece sua evolução.','Criar minha conta'],forgot:['RECUPERAR ACESSO','Redefinir minha senha.','Enviar e-mail'],newPassword:['NOVA SENHA','Escolha uma nova senha.','Salvar nova senha']};
 const [kicker,title,button]=labels[mode]||labels.login;
 const busy=loading?'disabled':'';
 return `<div class="login-page"><section class="login-art"><div class="login-brand"><span style="color:var(--accent)">◈</span> FORMA<b>.</b></div><div><div class="eyebrow">SEU ESPAÇO DE EVOLUÇÃO</div><h1>Mais forte.<br>Um dia<br>de cada vez<span class="accent">.</span></h1><p>Treinos, calendário e evolução. Seus dados, sua conta, sua jornada.</p></div><div class="login-numbers"><div class="login-number"><strong>ABC</strong><span>Treinos sob medida</span></div><div class="login-number"><strong>365</strong><span>Dias para evoluir</span></div><div class="login-number"><strong>100%</strong><span>Seu controle</span></div></div></section>
 <section class="login-right"><div class="login-box"><div class="login-theme-row">${themeToggle()}</div><div class="eyebrow">${kicker}</div><h2>${title}</h2><p class="muted small">${mode==='signup'?'Cadastre seu nome, e-mail e uma senha individual.':mode==='forgot'?'Informe o e-mail da conta para receber um link de recuperação.':mode==='newPassword'?'Abra este formulário pelo link enviado ao seu e-mail.':'Entre com seu e-mail e senha. Nenhum usuário é exibido publicamente.'}</p>
 ${a.setupError?`<div class="notice warn mt16">${esc(a.setupError)}</div>`:''}
 <form id="login-form" autocomplete="on">
 ${mode==='signup'?`<div class="field"><label for="auth-name">Seu nome</label><input class="control" id="auth-name" name="name" autocomplete="name" maxlength="70" placeholder="Como prefere ser chamado(a)" required ${busy}></div>`:''}
 ${mode==='newPassword'?'':`<div class="field mt12"><label for="auth-email">E-mail</label><input class="control" id="auth-email" name="email" type="email" autocomplete="${mode==='signup'?'email':'username'}" inputmode="email" placeholder="seuemail@exemplo.com" required ${busy}></div>`}
 ${mode==='login'||mode==='signup'||mode==='newPassword'?`<div class="field mt12"><label for="auth-password">${mode==='newPassword'?'Nova senha':'Senha'}</label><input class="control" id="auth-password" name="password" type="password" minlength="8" autocomplete="${mode==='login'?'current-password':'new-password'}" placeholder="Mínimo de 8 caracteres" required ${busy}></div>`:''}
 ${mode==='signup'||mode==='newPassword'?`<div class="field mt12"><label for="auth-confirm">Confirmar senha</label><input class="control" id="auth-confirm" name="confirm" type="password" minlength="8" autocomplete="new-password" placeholder="Repita sua senha" required ${busy}></div>`:''}
 <button class="btn btn-block mt16" type="submit" ${busy||a.setupError?'disabled':''}>${loading?'Aguarde...':button} ${icon('chevronRight')}</button>
 <p id="login-error" role="alert" class="small" style="color:var(--danger);min-height:16px;margin:12px 0 0">${esc(a.error||'')}</p></form>
 ${a.info?`<div role="status" class="notice mt12">${esc(a.info)}</div>`:''}
 <div class="auth-links">${mode==='login'?`<button data-action="auth-mode" data-mode="signup">Criar conta</button><button data-action="auth-mode" data-mode="forgot">Esqueci minha senha</button>`:`<button data-action="auth-mode" data-mode="login">Voltar para login</button>`}</div>
 <div class="login-footer">Dados protegidos por autenticação do Supabase e políticas de acesso por usuário. Não use a senha de outro serviço.</div>
 </div></section></div>`;
}
function renderShell(){const p=profile();let pg={dashboard:'Visão geral',calendar:'Calendário',routines:'Meus treinos',progress:'Evolução',weight:'Peso corporal',supplements:'Suplementos',library:'Biblioteca',settings:'Ajustes',live:'Treino ao vivo',insights:'Meu desempenho',body:'Medidas e fotos',plan:'Planejamento'};return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">F</span> FORMA<span class="accent">.</span></div><div class="nav-label">SEU PAINEL</div><nav class="nav">${navItem('Visão geral','dashboard','dashboard')}${navItem('Calendário','calendar','calendar')}${navItem('Treino ao vivo','live','dumbbell')}${navItem('Planejamento','plan','calendar')}${navItem('Treinos A / B / C','routines','dumbbell')}${navItem('Evolução','progress','chart')}${navItem('Desempenho e recordes','insights','target')}${navItem('Medidas e fotos','body','scale')}${navItem('Peso corporal','weight','scale')}${navItem('Suplementos','supplements','pill')}</nav><div class="nav-label mt20">PERSONALIZAÇÃO</div><nav class="nav">${navItem('Exercícios','library','library')}${navItem('Ajustes e backup','settings','settings')}</nav><div class="sidebar-bottom"><div class="sidebar-tip"><div class="gap10 bright">${icon('target')} <strong class="small">Sua constância conta</strong></div><p>Treino, cardio, abdômen e descanso têm seu lugar. Acompanhe cada etapa.</p></div><div class="profile-mini"><span class="avatar ${''}">${esc(p.name[0])}</span><span><b class="small">${esc(p.name)}</b><small>Perfil individual</small></span><button data-action="logout" title="Sair da conta" aria-label="Sair da conta">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">FORMA / ${pg[state.page]}</div><div class="top-actions"><span id="cloud-status" class="cloud-status" role="status">${esc(window.formaSyncText||"Conectado")}</span>${themeToggle()}<span class="today-pill">${icon('calendar')} ${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'short',year:'numeric'})}</span><button class="btn btn-secondary btn-small" data-action="logout">${icon('logout')} Sair da conta</button></div></header><div id="page-content">${renderPage()}</div></main><nav class="mobile-nav">${mobileItem('Início','dashboard','dashboard')}${mobileItem('Calendário','calendar','calendar')}${mobileItem('Treinos','routines','dumbbell')}${mobileItem('Evolução','progress','chart')}${mobileItem('Mais','settings','settings')}</nav><button class="floating-plus" data-action="fab" title="Ações rápidas" aria-label="Ações rápidas">${icon(state.fab?'x':'plus',24)}</button>${state.fab?`<div class="fab-menu"><button data-action="open-day" data-date="${today()}">${icon('calendar')} Registrar hoje</button><button data-action="add-weight">${icon('scale')} Adicionar peso</button><button data-action="new-exercise">${icon('plus')} Novo exercício</button><button data-action="new-supplement">${icon('pill')} Novo suplemento</button></div>`:''}</div>${renderModal()}`;}
function renderPage(){switch(state.page){case 'live':return renderLive();case 'insights':return renderInsights();case 'body':return renderBody();case 'plan':return renderPlan();case 'calendar':return renderCalendar();case 'routines':return renderRoutines();case 'progress':return renderProgress();case 'weight':return renderWeight();case 'supplements':return renderSupplements();case 'library':return renderLibrary();case 'settings':return renderSettings();default:return renderDashboard();}}
function render(){applyTheme();document.getElementById('app').innerHTML=current?renderShell():renderLogin();}
function toast(t,err=false){const el=document.getElementById('toast');el.textContent=t;el.style.background=err?'#ffb3ac':'#d4faa4';el.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.remove('show'),3000);}
function renderDashboard(){const p=profile(),now=today(),month=now.slice(0,7),thisMonthDays=Number(now.slice(8)),maxSupp=suppInMonth(month),weight=lastWeight(),lastSessions=workoutDates().reverse().slice(0,4),st=streakStats();
 const summary=[{icon:'dumbbell',value:workoutsInMonth(month),label:'Treinos neste mês',hint:'Treinos A, B e C registrados'},{icon:'calendar',value:maxSupp+'/'+thisMonthDays,label:'Dias suplementados',hint:'Do início do mês até hoje',cls:'purple'},{icon:'scale',value:weight?nfmt(weight.weight,1)+' kg':'—',label:'Último peso',hint:weight?'Em '+shortDate(weight.date):'Adicione seu primeiro peso',cls:'blue'},{icon:'target',value:p.exercises.filter(x=>!x.archived).length+EXERCISES.length,label:'Exercícios disponíveis',hint:'Você pode criar mais',cls:'amber'}];
 const start=shiftDate(now,-6),week=Array.from({length:7},(_,i)=>shiftDate(start,i));
 const dayStrip=`<div class="day-stripe">${week.map(d=>{const r=day(d),a=activity(r,d);return `<button class="${d===now?'today':''} ${a==='rest'?'rest':''}" data-action="open-day" data-date="${d}" title="${esc(longDate(d))}"><span class="dayname">${dateObj(d).toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}</span><span class="num">${Number(d.slice(8))}</span><span class="mini-type">${a==='rest'?'·':a==='cardio'?'C':a==='abs'?'ABS':a||'·'}</span><span class="supp-indicator ${hasSupp(r)?'':'off'}" title="${hasSupp(r)?'Suplementação registrada':'Sem suplementação'}"></span></button>`;}).join('')}</div>`;
 const todaySupp=p.supplements.map(s=>{const checked=(day(now).taken||[]).includes(s.id);return `<label class="supp-line"><input class="check" type="checkbox" data-today-supp="${esc(s.id)}" ${checked?'checked':''}><span class="grow"><span class="supp-name">${esc(s.name)}</span><span class="supp-meta">${esc(s.brand||'')}${s.dose?' · '+esc(s.dose):''} · ${esc(s.frequency||'Quando usar')}</span></span>${checked?tag('Tomado','purple'):''}</label>`;}).join('');
 return `${pageHeading('SEU PAINEL',`Olá, ${esc(p.name)} <span class="accent">✦</span>`, 'Cada registro é um passo na sua evolução. Organize seus treinos e acompanhe sua constância.', `<button class="btn" data-action="open-day" data-date="${now}">${icon('plus')} Registrar treino</button>`)}
 <section class="hero hero-streak"><div class="hero-copy"><span class="tag green">● SEU DIA DE HOJE</span><h2>Movimente-se no seu ritmo.</h2><p>${activity(day(now),now)==='rest'?'Hoje ainda não há treino registrado. É dia de descanso até você marcar outra atividade.':`Hoje: ${actLabel(day(now).activity)}. Continue registrando seu progresso.`} ${hasSupp(day(now))?'Suplementação registrada.':'Suplementação ainda não registrada.'}</p><div class="hero-actions"><button class="btn btn-paid" data-action="paid-workout">${icon('check')} Treino tá pago! 🎉</button><button class="btn btn-secondary" data-action="open-day" data-date="${now}">${icon('calendar')} Editar hoje</button></div></div>${streakPanel()}</section>
 <div class="grid4 mt16">${summary.map(x=>`<div class="card stat"><div class="icon-bubble ${x.cls||''}">${icon(x.icon)}</div><div class="stat-value mono">${x.value}</div><div class="stat-label">${x.label}</div><div class="stat-sub">${x.hint}</div></div>`).join('')}</div>
 <div class="section-head"><h2>Meus treinos</h2><button class="btn btn-small btn-ghost" data-action="page" data-page="routines">Personalizar ${icon('chevronRight')}</button></div>
 <div class="grid3">${['A','B','C'].map(letter=>{const r=p.routines[letter];return `<div class="card routine-card"><div class="routine-top"><div class="letter letter-${letter.toLowerCase()}">${letter}</div><div><h3>Treino ${letter}</h3><div class="muted small">${esc(r.name)}</div></div></div><div class="machine-icons">${r.exerciseIds.slice(0,4).map(id=>`<span class="machine-badge" title="${esc(exById(id).name)}">${{'Peito':'◉','Costas':'↟','Pernas':'▥','Glúteos':'◌','Braços':'↗','Ombros':'◆'}[exById(id).group]||'✶'}</span>`).join('')}<span class="count">${r.exerciseIds.length} exercícios</span></div><p class="routine-desc">${r.exerciseIds.slice(0,3).map(id=>exById(id).name).join(' · ')||'Escolha os exercícios deste treino.'}</p><button class="btn btn-secondary btn-small btn-block" data-action="edit-routine" data-routine="${letter}">Editar treino ${letter} ${icon('chevronRight')}</button></div>`}).join('')}</div>
 <div class="grid-main mt16"><div class="card"><div class="card-header"><div><h2>Últimos 7 dias</h2><p class="section-note">Treino e suplementação têm marcações distintas.</p></div><button class="btn btn-small btn-ghost" data-action="page" data-page="calendar">Calendário ${icon('chevronRight')}</button></div>${dayStrip}<div class="legend mt16"><span><i class="legend-dot"></i> Treino A/B/C ou atividade</span><span><i class="legend-dot" style="background:var(--violet)"></i> Suplementou</span><span><i class="legend-dot" style="background:#344045"></i> Não suplementou</span></div></div><div class="card"><div class="card-header"><div><h2>Suplementos de hoje</h2><p class="section-note">Marque individualmente o que tomou.</p></div>${icon('pill',21)}</div>${todaySupp||empty('pill','Sem suplementos','Adicione os suplementos que utiliza.')}<div class="mt16"><button class="btn btn-secondary btn-small btn-block" data-action="page" data-page="supplements">Gerenciar suplementos ${icon('chevronRight')}</button></div></div></div>
 <div class="section-head"><h2>Treinos recentes</h2><button class="btn btn-ghost btn-small" data-action="page" data-page="progress">Ver evolução ${icon('chevronRight')}</button></div>
 <div class="card">${lastSessions.length?`<div class="activity-list">${lastSessions.map(d=>{const rec=day(d);return `<div class="activity-item"><div class="activity-date">${Number(d.slice(8))}<small>${dateObj(d).toLocaleDateString('pt-BR',{month:'short'})}</small></div><div class="activity-text"><strong>${actLabel(rec.activity)} — ${esc(p.routines[rec.activity]?.name||'')}</strong><span>${(rec.session||[]).length} exercícios · ${(rec.session||[]).filter(x=>numberVal(x.weight)>0).length} com carga registrada</span></div>${tag('Concluído',actColor(rec.activity))}<button class="btn btn-icon btn-ghost" data-action="open-day" data-date="${d}" title="Editar">${icon('edit')}</button></div>`;}).join('')}</div>`:empty('clock','Nenhum treino ainda','Registre seu primeiro treino para começar o histórico.',`<button class="btn btn-small" data-action="open-day" data-date="${now}">Registrar treino</button>`)}</div>`;
}
function renderCalendar(){const y=Number(state.calendarMonth.slice(0,4)),m=Number(state.calendarMonth.slice(5)),first=new Date(y,m-1,1),startOffset=(first.getDay()+6)%7,numDays=new Date(y,m,0).getDate(),sel=state.selectedDate,rec=day(sel),selAct=activity(rec,sel);
 const blank=Array.from({length:startOffset},()=>`<div></div>`).join('');
 const days=Array.from({length:numDays},(_,i)=>{const ds=`${y}-${pad(m)}-${pad(i+1)}`,record=day(ds),a=activity(record,ds),future=ds>today();return `<button class="calendar-day ${ds===today()?'today':''} ${ds===sel?'active':''} ${future?'future':''}" data-action="open-day" data-date="${ds}" title="Abrir ${esc(longDate(ds))}"><span class="cal-top"><span class="calnum">${i+1}</span></span>${a?`<span class="cal-tag ${actColor(a)}">${a==='rest'?'Descanso':a==='cardio'?'Cardio':a==='abs'?'ABS':'Treino '+a}</span>`:''}${hasSupp(record)?`<span class="supp-mini"><span class="supp-indicator"></span> Suplementou</span>`:(!future?`<span class="supp-mini"><span class="supp-indicator off"></span> Sem suplemento</span>`:'')}</button>`;}).join('');
 const p=profile(),selSession=(rec.session||[]),monthTitle=first.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
 return `${pageHeading('CONSISTÊNCIA', 'Seu calendário<span class="accent">.</span>','Treinos e suplementos são marcados separadamente. Toque em qualquer dia para registrar ou editar.')}
 <div class="calendar-layout"><div class="card"><div class="between flex-wrap mb16"><div class="calendar-month">${esc(monthTitle)}</div><div class="calendar-controls"><button class="btn btn-small btn-ghost btn-icon" data-action="month-prev" title="Mês anterior">${icon('chevronLeft')}</button><button class="btn btn-small btn-ghost" data-action="month-today">Hoje</button><button class="btn btn-small btn-ghost btn-icon" data-action="month-next" title="Próximo mês">${icon('chevronRight')}</button></div></div><div class="calendar-grid">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>`<div class="calendar-weekday">${x}</div>`).join('')}${blank}${days}</div><div class="divider"></div><div class="legend"><span>${tag('A','green')} Treino A</span><span>${tag('B','purple')} Treino B</span><span>${tag('C','amber')} Treino C</span><span>${tag('Cardio / ABS','blue')} Atividade</span><span><i class="legend-dot" style="background:var(--violet)"></i> Suplementou</span><span><i class="legend-dot" style="background:#344045"></i> Não suplementou</span></div><div class="notice mt16">Regra automática: dia passado ou atual sem atividade marcada = <strong>descanso</strong>. Sem suplemento registrado = <strong>não suplementou</strong>. Um dia apenas com suplemento continua sendo descanso. Datas futuras não são classificadas.</div></div>
 <div class="calendar-aside"><div class="card streak-aside">${streakPanel(true)}<p class="hint mt12">Treinos A/B/C, cardio e abdominal contam. Descanso e suplementação isolada não contam. A sequência permanece até o fim do dia seguinte ao último treino.</p></div><div class="card"><div class="uppercase muted mb16">RESUMO DO MÊS</div><div class="between"><div><div class="stat-value">${workoutsInMonth(state.calendarMonth)}</div><div class="stat-label">Treinos A/B/C</div></div><div><div class="stat-value" style="color:var(--violet)">${suppInMonth(state.calendarMonth)}</div><div class="stat-label">Dias suplementados</div></div></div><div class="divider"></div><div class="small muted">Contagem de atividades extras: ${Object.entries(p.days).filter(([dt,r])=>dt.startsWith(state.calendarMonth)&&['cardio','abs'].includes(r.activity)).length} dias de cardio/ABS.</div></div><div class="card mt16"><div class="uppercase muted">DIA SELECIONADO</div><div class="mt16"><div class="big-day">${Number(sel.slice(8))}</div><div class="small muted">${esc(longDate(sel))}</div></div><div class="day-status">${tag(actLabel(selAct),actColor(selAct))}<h3>${selAct&&isWorkout(selAct)?`Treino ${selAct}: ${esc(p.routines[selAct]?.name)}`:actLabel(selAct)}</h3><p>${isWorkout(selAct)?`${selSession.length} exercícios no registro do dia.`:selAct==='cardio'||selAct==='abs'?'Atividade complementar registrada.':'Dia de descanso (marcado ou automático).'}</p></div><div class="between mb16"><span class="small muted">Suplementação</span>${tag(hasSupp(rec)?'Registrada':'Não registrada',hasSupp(rec)?'purple':'outline')}</div><button class="btn btn-block" data-action="open-day" data-date="${sel}">${icon('edit')} Editar este dia</button></div></div></div>`;
}
function renderRoutines(){const l=state.routine,r=profile().routines[l];return `${pageHeading('TREINOS PERSONALIZÁVEIS','Treinos A, B e C<span class="accent">.</span>','Altere o nome, substitua exercícios por grupamento muscular e mantenha a sua ficha sempre atualizada.',`<button class="btn" data-action="open-day" data-date="${today()}">${icon('plus')} Registrar hoje</button>`)}
 <div class="card"><div class="tabs">${['A','B','C'].map(x=>`<button class="tab ${l===x?'active':''}" data-action="routine-tab" data-routine="${x}">Treino ${x} · ${esc(profile().routines[x].name)}</button>`).join('')}</div><div class="between flex-wrap"><div class="gap12"><div class="letter letter-${l.toLowerCase()}">${l}</div><div><div class="eyebrow mb0">MINHA FICHA</div><h2 style="margin-top:5px">Treino ${l}</h2></div></div><span class="tag green">${r.exerciseIds.length} exercícios</span></div><div class="input-row mt20"><div class="field"><label for="routine-name">Nome do treino</label><input class="control" id="routine-name" value="${esc(r.name)}" maxlength="65" placeholder="Ex.: Peito e tríceps"></div><div class="field" style="justify-content:end"><button class="btn btn-secondary" data-action="rename-routine">${icon('save')} Salvar nome</button></div></div><div class="divider"></div><div class="between flex-wrap mb8"><h3>Exercícios desta ficha</h3><button class="btn btn-small" data-action="open-picker" data-mode="add" data-routine="${l}">${icon('plus')} Adicionar exercício</button></div>
 ${r.exerciseIds.length?r.exerciseIds.map((id,i)=>{const ex=exById(id);return `<div class="workout-ex">${machineArt(ex)}<div class="ex-meta"><div class="ex-count">${pad(i+1)} · ${esc(ex.group)}</div><h3>${esc(ex.name)}</h3><p>${esc(ex.equipment)}${ex.secondary?' · '+esc(ex.secondary):''}</p></div><div class="ex-actions"><button class="btn btn-icon btn-ghost" data-action="move-ex" data-index="${i}" data-dir="-1" title="Subir exercício" ${i===0?'disabled':''}>${icon('arrowUp')}</button><button class="btn btn-icon btn-ghost" data-action="move-ex" data-index="${i}" data-dir="1" title="Descer exercício" ${i===r.exerciseIds.length-1?'disabled':''}>${icon('arrowDown')}</button><button class="btn btn-small btn-secondary" data-action="open-picker" data-mode="replace" data-routine="${l}" data-index="${i}">${icon('refresh')} Trocar</button><button class="btn btn-icon btn-danger" data-action="remove-ex" data-index="${i}" title="Remover exercício">${icon('x')}</button></div></div>`;}).join(''):empty('dumbbell','Ficha vazia','Adicione exercícios da biblioteca.',`<button class="btn" data-action="open-picker" data-mode="add" data-routine="${l}">Escolher exercícios</button>`)}
 <div class="notice mt20">Alterar sua ficha <strong>não apaga o histórico</strong>. Treinos já realizados preservam os exercícios, cargas, séries e repetições registrados naquele dia.</div></div>`;}
function filteredExercises(group,search){return allExercises().filter(x=>!x.archived&&(group==='Todos'||x.group===group)&&(!search||`${x.name} ${x.equipment} ${x.secondary||''}`.toLowerCase().includes(search.toLowerCase())));}
function groupFilters(type){const sel=type==='picker'?state.pickerFilter:state.filter;return `<div class="filter-pills">${GROUPS.map(g=>`<button class="${sel===g?'active':''}" data-action="${type==='picker'?'picker-group':'library-group'}" data-group="${g}">${g}</button>`).join('')}</div>`;}
function renderLibrary(){const items=filteredExercises(state.filter,state.search);return `${pageHeading('BIBLIOTECA PESSOAL','Todos os exercícios<span class="accent">.</span>','Explore máquinas de academia por músculo e crie seus próprios exercícios, inclusive com foto.',`<button class="btn" data-action="new-exercise">${icon('plus')} Novo exercício</button>`)}<div class="card"><div class="lib-controls"><div class="field grow"><label for="library-search">Buscar exercício, máquina ou movimento</label><input class="control" id="library-search" data-search="library" value="${esc(state.search)}" placeholder="Ex.: supino, crossover, extensora..."></div></div>${groupFilters('library')}<div class="between mb16"><span class="small muted">${items.length} exercícios encontrados · ${profile().exercises.length} personalizados</span><span class="tiny muted">Use o ícone de edição para colocar sua foto da máquina</span></div><div class="library-grid">${items.map(ex=>`<div class="library-card">${machineArt(ex)}<div class="library-content"><div>${tag(ex.group,ex.group==='Peito'?'green':'outline')} ${ex.custom?'<span class="custom-flag">● PERSONALIZADO</span>':''}</div><h3>${esc(ex.name)}</h3><div class="muted tiny">${esc(ex.equipment)}</div><div class="library-foot"><span class="tiny muted">${esc(ex.secondary||'')}</span><div class="gap6"><button class="btn btn-icon btn-ghost" data-action="photo-ex" data-id="${esc(ex.id)}" title="Adicionar foto real da máquina">${icon('edit')}</button><button class="btn btn-small btn-secondary" data-action="library-add" data-id="${esc(ex.id)}" title="Adicionar à ficha atual">${icon('plus')} Ficha ${state.routine}</button>${ex.custom?`<button class="btn btn-icon btn-danger" data-action="delete-custom" data-id="${esc(ex.id)}" title="Arquivar exercício">${icon('trash')}</button>`:''}</div></div></div></div>`).join('')}</div><input type="file" id="library-photo-input" accept="image/jpeg,image/png,image/webp" hidden>${items.length?'':empty('search','Nenhum exercício encontrado','Experimente outro termo ou crie seu próprio exercício.')}</div>`;}
function chartSVG(rows,metric='weight',unit='kg'){
 if(rows.length===0)return `<div class="chart-placeholder">${empty('chart','Nenhum dado para o gráfico','Registre carga, séries e repetições para começar.')}</div>`;
 const vals=rows.map(r=>metric==='volume'?numberVal(r.weight)*numberVal(r.sets)*numberVal(r.reps):numberVal(r[metric]));
 const w=670,h=270,L=56,R=25,T=23,B=43,mini=Math.min(0,...vals),maxi=Math.max(...vals),min=Math.max(0,mini===maxi?mini*.75:mini-(maxi-mini)*.15),max=maxi===min?min+1:maxi+(maxi-min)*.15;
 const x=i=>rows.length===1?(L+w-R)/2:L+(w-L-R)*i/(rows.length-1),y=v=>T+(h-T-B)*(1-(v-min)/(max-min));
 const points=vals.map((v,i)=>`${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');
 const grids=Array.from({length:5},(_,i)=>{const val=min+(max-min)*i/4,yp=y(val);return `<line x1="${L}" y1="${yp}" x2="${w-R}" y2="${yp}" stroke="var(--chart-grid)" stroke-dasharray="4 6"/><text x="${L-9}" y="${yp+4}" font-size="11" fill="var(--muted)" text-anchor="end">${nfmt(val,val<10?1:0)}</text>`;}).join('');
 const marks=rows.map((r,i)=>`<g><circle cx="${x(i)}" cy="${y(vals[i])}" r="5" fill="var(--accent)" stroke="var(--card)" stroke-width="2"/><title>${shortDate(r.date)}: ${nfmt(vals[i],1)} ${unit}</title></g>`).join('');
 const xticks=[...new Set([0,Math.floor((rows.length-1)/2),rows.length-1])].map(i=>`<text x="${x(i)}" y="${h-13}" font-size="11" fill="var(--muted)" text-anchor="middle">${shortDate(rows[i].date)}</text>`).join('');
 return `<div class="chart-box"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Histórico com ${rows.length} registros"><defs><linearGradient id="plot-grad" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="var(--accent)" stop-opacity=".28"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs>${grids}<polygon points="${L},${h-B} ${points} ${x(rows.length-1)},${h-B}" fill="url(#plot-grad)"/><polyline points="${points}" fill="none" stroke="var(--accent)" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/>${marks}${xticks}</svg></div>`;
}
function renderProgress(){let entries=getEntries(state.progressExercise);if(!allExercises().some(e=>e.id===state.progressExercise)){state.progressExercise=allExercises()[0].id;entries=getEntries(state.progressExercise);}
 const metric=state.progressMetric,value=e=>metric==='weight'?numberVal(e.weight):metric==='reps'?numberVal(e.reps):numberVal(e.weight)*numberVal(e.reps)*numberVal(e.sets),last=entries.at(-1),first=entries[0],peak=entries.length?Math.max(...entries.map(value)):0,unit=metric==='reps'?'reps':metric==='volume'?'kg·rep':'kg',label=metric==='weight'?'Carga':metric==='reps'?'Repetições':'Volume',diff=last&&first?value(last)-value(first):0;
 return `${pageHeading('RESULTADOS REAIS','Sua evolução<span class="accent">.</span>','Consulte as cargas, repetições e volume por exercício, mesmo após alterar as fichas de treino.')}
 <div class="card"><div class="input-row"><div class="field"><label>Exercício</label><select class="control" data-select="progress-exercise">${allExercises().map(ex=>`<option value="${esc(ex.id)}" ${ex.id===state.progressExercise?'selected':''}>${esc(ex.name)}${ex.archived?' (arquivado)':''}</option>`).join('')}</select></div><div class="field"><label>Indicador no gráfico</label><select class="control" data-select="progress-metric"><option value="weight" ${metric==='weight'?'selected':''}>Carga (kg)</option><option value="reps" ${metric==='reps'?'selected':''}>Repetições</option><option value="volume" ${metric==='volume'?'selected':''}>Volume (kg × séries × reps)</option></select></div></div><div class="section-head"><div><h2>${esc(exById(state.progressExercise).name)}</h2><p class="section-note">Evolução de ${label.toLowerCase()} em cada sessão registrada.</p></div>${tag(entries.length+' registros','green')}</div><div class="chart-legend"><i></i>${label} (${unit})</div>${chartSVG(entries,metric,unit)}<div class="metric-row"><div class="metric"><span>ÚLTIMO VALOR</span><strong>${last?nfmt(value(last),metric==='reps'?0:1):'—'}</strong><span>${unit}</span></div><div class="metric"><span>MELHOR MARCA</span><strong>${entries.length?nfmt(peak,metric==='reps'?0:1):'—'}</strong><span>${unit}</span></div><div class="metric"><span>DESDE O PRIMEIRO</span><strong class="${diff>0?'bright':''}">${entries.length>1?(diff>0?'+':'')+nfmt(diff,1):'—'}</strong><span>${unit}</span></div></div></div>
 <div class="section-head"><h2>Histórico do exercício</h2></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Carga</th><th>Séries</th><th>Reps</th><th>Volume</th><th>Observação</th><th></th></tr></thead><tbody>${entries.slice().reverse().map(e=>`<tr><td>${shortDate(e.date)}</td><td>${nfmt(numberVal(e.weight),1)} kg</td><td>${esc(e.sets||'—')}</td><td>${esc(e.reps||'—')}</td><td>${nfmt(numberVal(e.weight)*numberVal(e.sets)*numberVal(e.reps))}</td><td class="notes" title="${esc(e.notes)}">${esc(e.notes||'—')}</td><td><button class="btn btn-icon btn-ghost" data-action="open-day" data-date="${e.date}" title="Ver dia">${icon('edit')}</button></td></tr>`).join('')||'<tr><td colspan="7" class="muted" style="text-align:center;padding:35px">Sem registros para este exercício ainda.</td></tr>'}</tbody></table></div></div>`;
}
function renderWeight(){const rows=[...profile().weights].sort((a,b)=>a.date.localeCompare(b.date)),first=rows[0],last=rows.at(-1),delta=first&&last?last.weight-first.weight:0;return `${pageHeading('MEDIDAS CORPORAIS','Acompanhamento de peso<span class="accent">.</span>','Registre suas pesagens e acompanhe a tendência com o passar das semanas.',`<button class="btn" data-action="add-weight">${icon('plus')} Adicionar pesagem</button>`)}<div class="grid3"><div class="card stat"><div class="stat-label">Peso atual</div><div class="stat-value">${last?nfmt(last.weight,2)+' kg':'—'}</div><div class="stat-sub">${last?'Atualizado em '+shortDate(last.date):'Sem registro'}</div></div><div class="card stat"><div class="stat-label">Peso inicial</div><div class="stat-value">${first?nfmt(first.weight,2)+' kg':'—'}</div><div class="stat-sub">${first?'Registrado em '+shortDate(first.date):'Sem registro'}</div></div><div class="card stat"><div class="stat-label">Variação acumulada</div><div class="stat-value" style="color:${delta===0?'var(--text)':delta>0?'var(--accent)':'var(--blue)'}">${rows.length?(delta>0?'+':'')+nfmt(delta,2)+' kg':'—'}</div><div class="stat-sub">Valor positivo significa aumento de peso</div></div></div>
 <div class="card mt16"><div class="card-header"><h2>Curva de peso corporal</h2>${tag(rows.length+' pesagens','green')}</div>${chartSVG(rows,'weight','kg')}</div><div class="section-head"><h2>Registro de pesagens</h2></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Peso</th><th>Observação</th><th>Ação</th></tr></thead><tbody>${rows.slice().reverse().map(w=>`<tr><td>${shortDate(w.date)}</td><td><b>${nfmt(w.weight,2)} kg</b></td><td>${esc(w.note||'—')}</td><td><button class="btn btn-icon btn-danger" data-action="delete-weight" data-id="${esc(w.id)}" title="Excluir pesagem">${icon('trash')}</button></td></tr>`).join('')||'<tr><td colspan="4" style="text-align:center;padding:30px" class="muted">Adicione sua primeira pesagem.</td></tr>'}</tbody></table></div></div>`;}
function renderSupplements(){const p=profile(),date=today(),d=day(date),items=p.supplements;return `${pageHeading('HÁBITOS E ROTINA','Meus suplementos<span class="accent">.</span>','Cadastre o que usa e marque individualmente as doses tomadas. Cada dia suplementado recebe um indicador roxo no calendário.',`<button class="btn" data-action="new-supplement">${icon('plus')} Adicionar suplemento</button>`)}
 <div class="card mb16"><div class="between flex-wrap"><div><h2>Hoje · ${shortDate(date)}</h2><p class="section-note">${hasSupp(d)?'Há suplementação registrada neste dia.':'Ainda não há suplementação registrada.'}</p></div>${tag(hasSupp(d)?'● Suplementou':'○ Não registrado',hasSupp(d)?'purple':'outline')}</div>${items.length?`<div class="mt16">${items.map(s=>{const checked=(d.taken||[]).includes(s.id);return `<label class="supp-line"><input class="check" type="checkbox" data-today-supp="${esc(s.id)}" ${checked?'checked':''}><span class="grow"><span class="supp-name">${esc(s.name)}</span><span class="supp-meta">${esc(s.brand||'Sem marca')} · ${esc(s.dose||'Dose não informada')} · ${esc(s.frequency||'Quando usar')}</span></span>${checked?tag('Tomado','purple'):''}</label>`;}).join('')}</div>`:`<div class="mt16">${empty('pill','Nenhum suplemento cadastrado','Crie sua lista. Também é possível marcar suplementação manualmente no calendário.')}</div>`}<div class="mt16"><button class="btn btn-small btn-secondary" data-action="open-day" data-date="${date}">${icon('calendar')} Abrir registro de hoje</button></div></div>
 <div class="section-head"><h2>Minha lista</h2>${tag(items.length+' cadastrados')}</div><div class="grid3">${items.map(s=>`<div class="card supp-card"><div class="supp-head"><div class="supp-icon">${icon('pill')}</div><div><h3>${esc(s.name)}</h3><span class="small muted">${esc(s.brand||'Sem marca')}</span></div></div><div class="supp-details"><div class="between"><span>Dose</span><strong>${esc(s.dose||'A definir')}</strong></div><div class="between mt8"><span>Frequência</span><strong>${esc(s.frequency||'Quando usar')}</strong></div></div><div class="supp-actions"><button class="btn btn-small btn-ghost" data-action="edit-supplement" data-id="${esc(s.id)}">${icon('edit')} Editar</button><button class="btn btn-small btn-danger" data-action="delete-supplement" data-id="${esc(s.id)}">${icon('trash')} Excluir</button></div></div>`).join('')}</div><div class="notice mt16">O cadastro e o calendário servem para <strong>organizar o uso que você já escolheu</strong>; não representam indicação de doses ou avaliação de segurança. Pré-treino pode ser marcado apenas nos dias em que for utilizado.</div>`;}
function renderSettings(){return `${pageHeading('CONFIGURAÇÕES','Sua conta, suas regras<span class="accent">.</span>','Aparência, senha, backup e sincronização com Supabase.')}
 <div class="card theme-settings-card mb16"><div><div class="gap10 mb8">${icon('sun',22)} <h2>Aparência do aplicativo</h2></div><p class="small muted">Escolha o escuro neon ou branco-gelo com verde-escuro. A preferência acompanha sua conta.</p></div><div class="theme-options"><button class="theme-option ${themeForUser()==='dark'?'active':''}" data-action="theme-set" data-theme="dark" aria-pressed="${themeForUser()==='dark'}"><span class="theme-swatch theme-swatch-dark"><i></i><b></b><em></em></span><span>${icon('moon',16)} Escuro neon</span></button><button class="theme-option ${themeForUser()==='light'?'active':''}" data-action="theme-set" data-theme="light" aria-pressed="${themeForUser()==='light'}"><span class="theme-swatch theme-swatch-light"><i></i><b></b><em></em></span><span>${icon('sun',16)} Claro gelo</span></button></div></div>
 <div class="grid2"><div class="card"><div class="gap10 mb16">${icon('download',22)} <h2>Backup e restauração</h2></div><p class="small muted">Seus registros são sincronizados com o Supabase. Ainda recomendamos exportar backups periódicos.</p><div class="notice small mb16" id="cloud-details">${esc(window.formaSyncText||'Verificando sincronização...')}</div><button class="btn btn-secondary btn-block" data-action="cloud-retry">${icon('refresh')} Sincronizar agora</button><button class="btn btn-block mt12" data-action="export">${icon('download')} Exportar meu backup</button><label class="btn btn-secondary btn-block mt12" style="cursor:pointer">${icon('upload')} Importar backup (inclusive v2.1)<input id="import-file" type="file" accept=".json,application/json" hidden></label><p class="hint mt12">Importar substitui apenas os dados desta conta. Exporte antes para ter uma cópia.</p></div>
 <div class="card"><div class="gap10 mb16">${icon('settings',22)} <h2>Minha conta</h2></div><p class="small muted">Conectado como <strong>${esc(window.formaUserEmail||'')}</strong>. Sua senha é administrada pelo Supabase Auth.</p><form id="account-name-form"><div class="field"><label>Nome de exibição</label><input class="control" name="name" maxlength="70" value="${esc(profile().name)}" required></div><button class="btn btn-secondary mt12" type="submit">Salvar nome</button></form><div class="divider"></div><form id="account-password-form"><div class="field"><label>Alterar senha</label><input class="control" name="password" type="password" minlength="8" autocomplete="new-password" placeholder="Nova senha com pelo menos 8 caracteres" required></div><div class="field mt12"><label>Confirmar nova senha</label><input class="control" name="confirm" type="password" minlength="8" autocomplete="new-password" required></div><button class="btn btn-secondary mt16" type="submit">${icon('save')} Atualizar senha</button></form><p class="hint mt12">Se esqueceu sua senha, saia e use “Esqueci minha senha” na tela de login.</p></div></div>
 <div class="card mt16"><div class="between flex-wrap"><div><h2>Limpar meus registros</h2><p class="section-note">Apaga treinos, calendário, suplementos, peso e fotos desta conta. Não exclui o cadastro de login.</p></div><button class="btn btn-danger" data-action="reset">${icon('trash')} Limpar registros</button></div></div>
 <div class="notice mt16">Versão de testes. Os registros são privados por conta mediante políticas RLS. Ao usar em dois aparelhos simultaneamente, a última gravação poderá substituir alterações mais antigas. Não compartilhe sua senha.</div>`;}
function renderModal(){if(!state.modal)return '';
 const wrap=(title,body,foot='',wide=false)=>`<div class="overlay" id="overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="btn btn-icon btn-ghost" data-action="close-modal" aria-label="Fechar">${icon('x')}</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-footer">${foot}</div>`:''}</section></div>`;
 if(state.modal==='day'){
 const d=state.dayDraft,dt=state.selectedDate,act=d.activity,items=profile().supplements,valid=!!act;
 const opts=['A','B','C','cardio','abs','rest'].map(a=>`<button class="activity-choice ${act===a?'selected':''}" data-action="choose-activity" data-type="${a}">${isWorkout(a)?icon('dumbbell'):a==='rest'?icon('clock'):icon('flame')}${actLabel(a)}</button>`).join('');
 let session='';if(isWorkout(act)){session=`<div class="section-head"><h3>Exercícios realizados</h3><span class="tiny muted">Use a carga efetivamente utilizada</span></div>${(d.session||[]).length?(d.session||[]).map((e,i)=>{const x=exById(e.id);return `<div class="session-item"><div class="ex-title">${pad(i+1)}. ${esc(e.name||x.name)}</div><div class="session-fields"><div><label>Carga (kg)</label><input class="control" type="number" inputmode="decimal" min="0" step="0.25" data-session-index="${i}" data-session-field="weight" value="${esc(e.weight)}" placeholder="Ex.: 30"></div><div><label>Séries</label><input class="control" type="number" min="0" step="1" data-session-index="${i}" data-session-field="sets" value="${esc(e.sets)}" placeholder="Ex.: 3"></div><div><label>Repetições</label><input class="control" type="number" min="0" step="1" data-session-index="${i}" data-session-field="reps" value="${esc(e.reps)}" placeholder="Ex.: 12"></div></div><textarea class="control" rows="2" data-session-index="${i}" data-session-field="notes" placeholder="Observação: execução, dificuldade, drop-set...">${esc(e.notes)}</textarea></div>`;}).join(''):empty('dumbbell','Treino sem exercícios','Vá em Treinos e adicione exercícios à ficha.')}<p class="hint">Registre a carga total que considera no exercício e use o mesmo padrão nas próximas sessões (por exemplo, soma dos dois lados). Para comparar a evolução, informe carga e repetições.</p>`;}
 if(['cardio','abs'].includes(act))session=`<div class="field mt16"><label>Duração (minutos, opcional)</label><input class="control" type="number" data-day-field="minutes" value="${esc(d.minutes||'')}" min="0" placeholder="Ex.: 30"></div>`;
 const suppControls=items.map(s=>`<label class="switch-line"><span><b>${esc(s.name)}</b><br><span class="tiny muted">${esc(s.dose||s.frequency||'')}</span></span><input type="checkbox" data-day-supp="${esc(s.id)}" ${(d.taken||[]).includes(s.id)?'checked':''}></label>`).join('');
 const globalChecked=d.supplemented && !(d.taken||[]).length;
 return wrap(`Registrar dia · ${shortDate(dt)}`,`<div class="small muted mb16">${esc(longDate(dt))}</div><div class="field"><label>O que você fez neste dia?</label><div class="activity-options">${opts}</div></div>${session}<div class="divider"></div><div class="between"><h3>Suplementação</h3>${tag((d.taken||[]).length||d.supplemented?'Registrada':'Não registrada',(d.taken||[]).length||d.supplemented?'purple':'outline')}</div><div class="mt8">${suppControls}</div><label class="switch-line"><span><b>Marcar suplementação geral</b><br><span class="tiny muted">Use se tomou suplementos mas não quer escolher um item</span></span><input type="checkbox" data-day-supp-general ${globalChecked?'checked':''}></label><div class="field mt16"><label>Observação sobre o dia</label><textarea class="control" rows="2" data-day-field="notes" placeholder="Ex.: treino muito bom, descanso, cansaço, caminhada...">${esc(d.notes||'')}</textarea></div>`, `<button class="btn btn-ghost" data-action="clear-day">Limpar dia</button>${isTrainingActivity(act)&&dt<=today()?`<button class="btn btn-paid" data-action="finish-workout">${icon('check')} Treino tá pago! 🎉</button>`:`<button class="btn" data-action="save-day">${icon('check')} Salvar registro</button>`}`,true);
 }
 if(state.modal==='picker'){
 const items=filteredExercises(state.pickerFilter,state.pickerSearch).filter(ex=>!(state.pickerMode==='add'&&profile().routines[state.pickerRoutine].exerciseIds.includes(ex.id)));
 return wrap(state.pickerMode==='replace'?'Substituir exercício':'Escolher exercício',`<p class="small muted">${state.pickerMode==='replace'?'Selecione uma opção para trocar o exercício sem apagar as sessões anteriores.':'Selecione um exercício para adicionar à sua ficha.'}</p><div class="field"><label>Buscar na biblioteca</label><input class="control" data-search="picker" value="${esc(state.pickerSearch)}" placeholder="Buscar pelo nome ou máquina..."></div><div class="mt12">${groupFilters('picker')}</div><div class="modal-picker-list">${items.map(ex=>`<button class="picker-ex" data-action="pick-ex" data-id="${esc(ex.id)}">${machineArt(ex)}<div class="ex-meta"><h3>${esc(ex.name)}</h3><span>${esc(ex.group)} · ${esc(ex.equipment)}</span></div>${icon('plus')}</button>`).join('')||empty('search','Nenhum exercício disponível','Use outro filtro ou crie um exercício novo.')}</div><div class="mt16"><button class="btn btn-small btn-secondary" data-action="new-exercise">${icon('plus')} Criar exercício personalizado</button></div>`);
 }
 if(state.modal==='newExercise')return wrap('Novo exercício personalizado',`<form id="exercise-form"><div class="field"><label>Nome do exercício *</label><input class="control" name="name" placeholder="Ex.: Supino reto com halteres" required maxlength="70"></div><div class="input-row mt12"><div class="field"><label>Grupamento muscular *</label><select class="control" name="group" required>${GROUPS.filter(g=>g!=='Todos').map(g=>`<option value="${g}">${g}</option>`).join('')}</select></div><div class="field"><label>Máquina ou equipamento</label><input class="control" name="equipment" placeholder="Ex.: Halteres" maxlength="60"></div></div><div class="field mt12"><label>Observação do exercício</label><textarea class="control" name="secondary" placeholder="Ex.: Foco em peitoral superior" maxlength="180"></textarea></div><div class="field mt12"><label>Foto da máquina (opcional, JPG/PNG/WebP)</label><input class="control" id="exercise-photo" type="file" accept="image/png,image/jpeg,image/webp"><span class="hint" id="photo-status">A imagem será reduzida para economizar espaço no navegador.</span></div><button type="submit" class="btn btn-block mt16">${icon('plus')} Criar exercício</button></form>`);
 if(state.modal==='newSupplement'||state.modal==='editSupplement'){
 const s=state.editSupplement?profile().supplements.find(s=>s.id===state.editSupplement):null;
 return wrap(s?'Editar suplemento':'Adicionar suplemento',`<form id="supplement-form"><div class="field"><label>Nome do suplemento *</label><input class="control" name="name" value="${esc(s?.name||'')}" placeholder="Ex.: Creatina" maxlength="70" required></div><div class="input-row mt12"><div class="field"><label>Marca</label><input class="control" name="brand" value="${esc(s?.brand||'')}" placeholder="Ex.: Growth" maxlength="60"></div><div class="field"><label>Dose usada</label><input class="control" name="dose" value="${esc(s?.dose||'')}" placeholder="Ex.: 3 g" maxlength="40"></div></div><div class="field mt12"><label>Frequência</label><select class="control" name="frequency">${['Diário','Dias de treino','Quando usar'].map(v=>`<option ${s?.frequency===v?'selected':''}>${v}</option>`).join('')}</select></div><p class="hint mt12">Este é um registro do seu consumo, não uma sugestão de dosagem.</p><button class="btn btn-block mt16" type="submit">${icon('save')} ${s?'Salvar alterações':'Adicionar'}</button></form>`);
 }
 if(state.modal==='weight')return wrap('Registrar pesagem',`<form id="weight-form"><div class="input-row"><div class="field"><label>Data</label><input class="control" type="date" name="date" value="${today()}" required></div><div class="field"><label>Peso (kg)</label><input class="control" type="number" step="0.01" min="1" max="500" name="weight" placeholder="Ex.: 67,30" required autofocus></div></div><div class="field mt12"><label>Observação</label><input class="control" name="note" maxlength="160" placeholder="Ex.: Em jejum, após acordar"></div><button class="btn btn-block mt16" type="submit">${icon('save')} Salvar peso</button></form>`);
 if(state.modal==='reset')return wrap('Redefinir perfil?',`<div class="notice warn">Você está prestes a apagar <strong>todos os registros deste perfil</strong>, incluindo treinos, evolução e pesos. Sua conta de login continuará ativa. Exporte um backup antes.</div><p class="small muted mt16">Digite <b>APAGAR</b> para confirmar.</p><input class="control" id="reset-confirm" placeholder="APAGAR">`,`<button class="btn btn-ghost" data-action="close-modal">Cancelar</button><button class="btn btn-danger" data-action="confirm-reset">Apagar dados</button>`);
 return '';
}
function openDay(dt){state.selectedDate=dt;state.calendarMonth=dt.slice(0,7);state.dayDraft=clone(day(dt));state.dayDraft.taken ||= [];state.dayDraft.session ||= [];state.modal='day';state.fab=false;render();}
function closeModal(){state.modal=null;state.dayDraft=null;state.photoData=null;render();}
function setActivity(a){const d=state.dayDraft;if(d.activity!==a){d.activity=a;d.session=isWorkout(a)?profile().routines[a].exerciseIds.map(id=>({id,name:exById(id).name,weight:'',sets:'',reps:'',notes:''})):[];d.minutes='';}renderModalOnly();}
function renderModalOnly(){const old=document.querySelector('.modal-body'),scroll=old?old.scrollTop:0;const existing=document.querySelector('.overlay');if(existing)existing.outerHTML=renderModal();else render();const newBody=document.querySelector('.modal-body');if(newBody)newBody.scrollTop=scroll;}
function rememberDay(celebrate=false,origin=null){const d=clone(state.dayDraft);d.taken=[...new Set(d.taken||[])];d.supplemented=!!d.supplemented||d.taken.length>0;
 if(!d.activity&&!d.notes&&!hasSupp(d))delete profile().days[state.selectedDate];else profile().days[state.selectedDate]=d;
 saveDB();state.modal=null;state.dayDraft=null;render();if(celebrate){confettiCelebration(origin);toast('Treino tá pago! Mais um dia registrado.');}else toast('Dia registrado no calendário!');}
function changeMonth(n){const [y,m]=state.calendarMonth.split('-').map(Number);const d=new Date(y,m-1+n,1);state.calendarMonth=`${d.getFullYear()}-${pad(d.getMonth()+1)}`;state.selectedDate=`${state.calendarMonth}-01`;render();}
function quickSupp(id,checked){const r=clone(day(today()));r.taken ||= [];if(checked){if(!r.taken.includes(id))r.taken.push(id);}else r.taken=r.taken.filter(x=>x!==id);r.supplemented=r.taken.length>0;profile().days[today()]=r;saveDB();render();toast(checked?'Suplemento registrado!':'Suplemento desmarcado.');}
function moveExercise(idx,dir){const ids=profile().routines[state.routine].exerciseIds,j=idx+dir;if(j<0||j>=ids.length)return;[ids[idx],ids[j]]=[ids[j],ids[idx]];saveDB();render();}
function openPicker(mode,routine,index){state.pickerMode=mode;state.pickerRoutine=routine;state.pickerIndex=index??-1;state.pickerFilter=mode==='replace'?exById(profile().routines[routine].exerciseIds[index]).group:'Todos';state.pickerSearch='';state.modal='picker';render();}
function addToRoutine(id,routine){const ids=profile().routines[routine].exerciseIds;if(ids.includes(id)){toast('Este exercício já está na ficha.');return false;}ids.push(id);saveDB();return true;}
function saveExercise(e){e.preventDefault();const f=new FormData(e.target);const name=String(f.get('name')||'').trim();if(!name)return;const item={id:'custom_'+uid(),name,group:String(f.get('group')),equipment:String(f.get('equipment')||'').trim()||'Personalizado',secondary:String(f.get('secondary')||'').trim(),kind:'chest',custom:true};if(state.photoData)item.photo=state.photoData;profile().exercises.push(item);if(state.creatingFromPicker){addToRoutine(item.id,state.pickerRoutine);state.page='routines';state.routine=state.pickerRoutine;}
 saveDB();state.modal=null;state.creatingFromPicker=false;state.photoData=null;render();toast('Exercício criado com sucesso!');}
function saveSupplement(e){e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')||'').trim();if(!name)return;const item={name,brand:String(f.get('brand')||'').trim(),dose:String(f.get('dose')||'').trim(),frequency:String(f.get('frequency')||'Quando usar')};if(state.editSupplement){const s=profile().supplements.find(s=>s.id===state.editSupplement);if(s)Object.assign(s,item);}else profile().supplements.push({id:'sup_'+uid(),...item});saveDB();state.modal=null;state.editSupplement=null;render();toast('Lista de suplementos atualizada!');}
function saveWeight(e){e.preventDefault();const f=new FormData(e.target),n=numberVal(f.get('weight')),date=String(f.get('date')||today());if(n<=0||n>500){toast('Informe um peso válido.',true);return;}profile().weights.push({id:uid(),date,weight:n,note:String(f.get('note')||'').trim()});saveDB();state.modal=null;state.page='weight';render();toast('Pesagem salva!');}
function exportBackup(){const copy=clone(profile());delete copy.pin;const exportData={format:'forma-profile-v1',profile:current,exportedAt:new Date().toISOString(),data:copy};const json=JSON.stringify(exportData,null,2),blob=new Blob([json],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`forma-backup-${today()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Backup exportado. Guarde o arquivo em local seguro.');}
async function importBackup(file){if(!file)return;try{if(file.size>15*1024*1024)throw Error('Arquivo maior que 15 MB.');const obj=JSON.parse(await file.text());if(obj.format!=='forma-profile-v1')throw Error('Selecione um backup JSON exportado pelo FORMA.');const d=obj.data;if(!d||!d.routines||!['A','B','C'].every(k=>Array.isArray(d.routines[k]?.exerciseIds))||!Array.isArray(d.weights)||!Array.isArray(d.exercises)||!Array.isArray(d.supplements)||!d.days||typeof d.days!=='object')throw Error('Arquivo inválido.');if(!window.confirm(`Importar dados do backup ${obj.profile||''} para ${profile().name}? Isso substituirá TODOS os registros desta conta. Faça backup dos dados atuais antes.`))return;const existing=profile();delete d.pin;db.profiles[current]={...d,name:existing.name,theme:d.theme==='light'?'light':d.theme==='dark'?'dark':existing.theme};saveDB();state.modal=null;state.page='dashboard';state.progressExercise='supino';render();toast('Backup importado. Aguarde a confirmação de sincronização.');}catch(err){toast(err.message||'Falha ao importar backup.',true);}}
function restoreFocusedInput(which,fn){const src=document.activeElement,start=src?.selectionStart??null;fn();const el=document.querySelector(`[data-search="${which}"]`);if(el){el.focus();try{if(start!==null)el.setSelectionRange(start,start);}catch(_){}}}
function actionHandler(e){const btn=e.target.closest('[data-action]');if(!btn)return;const ac=btn.dataset.action;
 switch(ac){
 case 'auth-mode':window.formaSetAuthMode?.(btn.dataset.mode);return;
  case 'auth-retry':window.formaRetryLoad?.();return;
 case 'theme-toggle':setTheme();return;
 case 'theme-set':{const v=btn.dataset.theme;if(v!=='light'&&v!=='dark')return;profile().theme=v;saveDB();render();toast('Tema '+(v==='light'?'claro gelo':'escuro neon')+' salvo.');return;}
 case 'page':state.page=btn.dataset.page;state.modal=null;state.fab=false;render();window.scrollTo(0,0);return;
 case 'logout':window.formaLogout?.();return;
 case 'fab':state.fab=!state.fab;render();return;
 case 'open-day':openDay(btn.dataset.date);return;
 case 'close-modal':closeModal();return;
 case 'choose-activity':setActivity(btn.dataset.type);return;
 case 'save-day':rememberDay();return;
 case 'finish-workout':{
  if(!state.dayDraft||!isTrainingActivity(state.dayDraft.activity)||state.selectedDate>today())return;
  const origin=btn.getBoundingClientRect();rememberDay(true,origin);return;
 }
 case 'paid-workout':{
  if(isTrainingActivity(day(today()).activity)){
   confettiCelebration(btn.getBoundingClientRect());toast('Treino tá pago! Seu registro de hoje já está salvo.');
  }else openDay(today());
  return;
 }
 case 'clear-day':if(!confirm('Limpar atividade e suplementação deste dia?'))return;delete profile().days[state.selectedDate];saveDB();state.modal=null;render();toast('Registro do dia apagado.');return;
 case 'month-prev':changeMonth(-1);return;
 case 'month-next':changeMonth(1);return;
 case 'month-today':state.calendarMonth=today().slice(0,7);state.selectedDate=today();render();return;
 case 'routine-tab':state.routine=btn.dataset.routine;render();return;
 case 'edit-routine':state.routine=btn.dataset.routine;state.page='routines';render();window.scrollTo(0,0);return;
 case 'rename-routine':{const name=document.getElementById('routine-name').value.trim();if(!name)return toast('Informe um nome.',true);profile().routines[state.routine].name=name;saveDB();render();toast('Nome do treino salvo!');return;}
 case 'move-ex':moveExercise(Number(btn.dataset.index),Number(btn.dataset.dir));return;
 case 'remove-ex':{const ids=profile().routines[state.routine].exerciseIds;ids.splice(Number(btn.dataset.index),1);saveDB();render();toast('Exercício removido da ficha.');return;}
 case 'open-picker':openPicker(btn.dataset.mode,btn.dataset.routine,Number(btn.dataset.index));return;
 case 'picker-group':state.pickerFilter=btn.dataset.group;renderModalOnly();return;
 case 'library-group':state.filter=btn.dataset.group;render();return;
 case 'pick-ex':{const r=profile().routines[state.pickerRoutine],id=btn.dataset.id;if(state.pickerMode==='replace'){const old=r.exerciseIds[state.pickerIndex];if(id!==old&&r.exerciseIds.includes(id))return toast('Esse exercício já está nessa ficha.',true);r.exerciseIds[state.pickerIndex]=id;}else if(!addToRoutine(id,state.pickerRoutine))return;saveDB();state.routine=state.pickerRoutine;state.modal=null;state.page='routines';render();toast('Ficha atualizada! O histórico anterior foi preservado.');return;}
 case 'library-add':if(addToRoutine(btn.dataset.id,state.routine))toast('Adicionado ao Treino '+state.routine+'!');return;
 case 'photo-ex':state.photoTarget=btn.dataset.id;document.getElementById('library-photo-input')?.click();return;
 case 'new-exercise':state.creatingFromPicker=state.modal==='picker';state.photoData=null;state.modal='newExercise';state.fab=false;render();return;
 case 'delete-custom':{const ex=profile().exercises.find(x=>x.id===btn.dataset.id);if(!ex||!confirm(`Arquivar "${ex.name}"? Ele sairá das fichas, mas o histórico será preservado.`))return;ex.archived=true;Object.values(profile().routines).forEach(r=>r.exerciseIds=r.exerciseIds.filter(id=>id!==ex.id));saveDB();render();toast('Exercício arquivado. Histórico preservado.');return;}
 case 'new-supplement':state.editSupplement=null;state.modal='newSupplement';state.fab=false;render();return;
 case 'edit-supplement':state.editSupplement=btn.dataset.id;state.modal='editSupplement';render();return;
 case 'delete-supplement':{const id=btn.dataset.id,s=profile().supplements.find(x=>x.id===id);if(!s||!confirm(`Excluir "${s.name}" da sua lista? As marcações históricas do dia serão mantidas.`))return;profile().supplements=profile().supplements.filter(x=>x.id!==id);saveDB();render();toast('Suplemento excluído da lista.');return;}
 case 'add-weight':state.modal='weight';state.fab=false;render();return;
 case 'delete-weight':if(confirm('Apagar esta pesagem?')){profile().weights=profile().weights.filter(w=>w.id!==btn.dataset.id);saveDB();render();toast('Pesagem apagada.');}return;
 case 'export':exportBackup();return;
 case 'cloud-retry':window.formaForceSave?.();return;
  case 'reset':state.modal='reset';render();return;
 case 'confirm-reset':if(document.getElementById('reset-confirm')?.value!=='APAGAR')return toast('Digite APAGAR para confirmar.',true);{const t=themeForUser(),name=profile().name;db.profiles[current]=makeProfile(name);db.profiles[current].theme=t;}saveDB();state.page='dashboard';state.modal=null;render();toast('Perfil redefinido.');return;
 }
}
document.addEventListener('click',e=>{if(e.target.id==='overlay'){closeModal();return;}actionHandler(e);});
document.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();window.formaAuthSubmit?.(e.target);return;}
 if(e.target.id==='exercise-form')return saveExercise(e);
 if(e.target.id==='supplement-form')return saveSupplement(e);
 if(e.target.id==='weight-form')return saveWeight(e);
  if(e.target.id==='account-password-form'){e.preventDefault();window.formaChangePassword?.(e.target);return;}
  if(e.target.id==='account-name-form'){e.preventDefault();window.formaChangeName?.(e.target);return;}
});
document.addEventListener('input',e=>{
 const el=e.target;
 if(el.dataset.search){const which=el.dataset.search;if(which==='picker')state.pickerSearch=el.value;else state.search=el.value;restoreFocusedInput(which,()=>{if(which==='picker')renderModalOnly();else render();});return;}
 if(el.dataset.sessionField&&state.modal==='day'){const item=state.dayDraft.session[Number(el.dataset.sessionIndex)];if(item)item[el.dataset.sessionField]=el.value;return;}
 if(el.dataset.dayField&&state.modal==='day'){state.dayDraft[el.dataset.dayField]=el.value;return;}
});
document.addEventListener('change',async e=>{const el=e.target;
 if(el.dataset.todaySupp){quickSupp(el.dataset.todaySupp,el.checked);return;}
 if(el.dataset.daySupp&&state.modal==='day'){const id=el.dataset.daySupp,d=state.dayDraft;d.taken ||= [];if(el.checked){if(!d.taken.includes(id))d.taken.push(id);}else d.taken=d.taken.filter(x=>x!==id);d.supplemented=d.taken.length>0;renderModalOnly();return;}
 if('daySuppGeneral' in el.dataset&&state.modal==='day'){state.dayDraft.supplemented=el.checked;renderModalOnly();return;}
 if(el.dataset.select==='progress-exercise'){state.progressExercise=el.value;render();return;}
 if(el.dataset.select==='progress-metric'){state.progressMetric=el.value;render();return;}
 if(el.id==='import-file'){await importBackup(el.files[0]);return;}
 if(el.id==='library-photo-input'&&el.files[0]){const file=el.files[0];if(file.size>8*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))return toast('Foto inválida ou maior que 8 MB.',true);try{const photo=await compressPhoto(file);profile().exercisePhotos ||= {};profile().exercisePhotos[state.photoTarget]=photo;saveDB();render();toast('Foto da máquina atualizada!');}catch(err){toast('Falha ao processar a imagem.',true);}return;}
 if(el.id==='exercise-photo'&&el.files[0]){const file=el.files[0];if(file.size>8*1024*1024){toast('Imagem muito grande (máximo 8 MB).',true);return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Use uma imagem JPG, PNG ou WebP.',true);return;}try{state.photoData=await compressPhoto(file);const label=document.getElementById('photo-status');if(label)label.textContent='Foto pronta para salvar.';toast('Foto adicionada!');}catch(err){toast('Não foi possível processar a foto.',true);}return;}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal)closeModal();});
function compressPhoto(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const im=new Image();im.onerror=reject;im.onload=()=>{const scale=Math.min(1,360/Math.max(im.width,im.height)),cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(im.width*scale));cv.height=Math.max(1,Math.round(im.height*scale));const ctx=cv.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,cv.width,cv.height);ctx.drawImage(im,0,0,cv.width,cv.height);resolve(cv.toDataURL('image/jpeg',.74));};im.src=reader.result;};reader.readAsDataURL(file);});}
